class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for t in tokens:
            if t not in ("+", "-", "*", "/"):
                stack.append(int(t))            # 数字直接压栈
                continue
            b = stack.pop()                     # 先弹出的是右边的数
            a = stack.pop()
            if t == "+":
                stack.append(a + b)
            elif t == "-":
                stack.append(a - b)
            elif t == "*":
                stack.append(a * b)
            else:
                stack.append(int(a / b))        # 向零取整
        return stack[0]

