class Solution {
    public int evalRPN(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String t : tokens) {
            if (t.length() > 1 || Character.isDigit(t.charAt(0))) {     // 长度大于 1 的一定是数字，比如 "-11"
                stack.push(Integer.parseInt(t));        // 数字直接压栈
                continue;
            }
            int b = stack.pop();                        // 先弹出的是右边的数
            int a = stack.pop();
            switch (t) {
                case "+": stack.push(a + b); break;
                case "-": stack.push(a - b); break;
                case "*": stack.push(a * b); break;
                default: stack.push(a / b);             // 整数除法本来就向零取整
            }
        }
        return stack.pop();
    }
}

