    int evalRPN(vector<string>& tokens) {
        stack<long long> st;
        for (auto& t : tokens) {
            if (t.size() > 1 || isdigit(t[0])) {        // 长度大于 1 的一定是数字，比如 "-11"
                st.push(stoll(t));                      // 数字直接压栈
                continue;
            }
            long long b = st.top(); st.pop();           // 先弹出的是右边的数
            long long a = st.top(); st.pop();
            if (t == "+") {
                st.push(a + b);
            } else if (t == "-") {
                st.push(a - b);
            } else if (t == "*") {
                st.push(a * b);
            } else {
                st.push(a / b);                         // 整数除法本来就向零取整
            }
        }
        return (int)st.top();
    }
};

