	stack := []int{}
	for _, t := range tokens {
		if len(t) > 1 || (t[0] >= '0' && t[0] <= '9') { // 长度大于 1 的一定是数字，比如 "-11"
			v, _ := strconv.Atoi(t)
			stack = append(stack, v) // 数字直接压栈
			continue
		}
		b := stack[len(stack)-1] // 先弹出的是右边的数
		a := stack[len(stack)-2]
		stack = stack[:len(stack)-2]
		switch t {
		case "+":
			stack = append(stack, a+b)
		case "-":
			stack = append(stack, a-b)
		case "*":
			stack = append(stack, a*b)
		default:
			stack = append(stack, a/b) // 整数除法本来就向零取整
		}
	}
	return stack[0]
}

