class MyQueue:
    def __init__(self):
        self.inbox = []                 # 新元素都压进这里
        self.outbox = []                # 出队都从这里弹

    def push(self, x: int) -> None:
        self.inbox.append(x)

    def pop(self) -> int:
        self.peek()                     # 先保证 outbox 里有元素
        return self.outbox.pop()

    def peek(self) -> int:
        if not self.outbox:             # outbox 空了才倒
            while self.inbox:           # 把 inbox 整个倒过来
                self.outbox.append(self.inbox.pop())
        return self.outbox[-1]

    def empty(self) -> bool:
        return not self.inbox and not self.outbox

