class MyQueue {
    private final Deque<Integer> inbox = new ArrayDeque<>();     // 新元素都压进这里
    private final Deque<Integer> outbox = new ArrayDeque<>();    // 出队都从这里弹

    public void push(int x) {
        inbox.push(x);
    }

    public int pop() {
        peek();                                 // 先保证 outbox 里有元素
        return outbox.pop();
    }

    public int peek() {
        if (outbox.isEmpty()) {                 // outbox 空了才倒
            while (!inbox.isEmpty()) {          // 把 inbox 整个倒过来
                outbox.push(inbox.pop());
            }
        }
        return outbox.peek();
    }

    public boolean empty() {
        return inbox.isEmpty() && outbox.isEmpty();
    }
}

