        inbox.push(x);
    }

    int pop() {
        int x = peek();                         // 先保证 outbox 里有元素
        outbox.pop();
        return x;
    }

    int peek() {
        if (outbox.empty()) {                   // outbox 空了才倒
            while (!inbox.empty()) {            // 把 inbox 整个倒过来
                outbox.push(inbox.top());
                inbox.pop();
            }
        }
        return outbox.top();
    }

    bool empty() {
        return inbox.empty() && outbox.empty();
    }
};

